-- Reversa de 0351: devuelve las reglas 1 y 6 de las instrucciones de la IA de Panamá a como estaban.
update confirmacion_ia_config c
set instrucciones = replace(replace(c.instrucciones, '1) CIUDAD = las 6 zonas de delivery y todo lo de dentro de la línea roja del mapa (de Amador, Naos y Flamenco hasta Alcalde Díaz, Tocumen y Pacora). Zonas 5 y 6: la tendencia CLARA de la tienda (Kenku suele INTERIOR; Nuvo y Oferfy, CIUDAD); si es mixta o no hay, CIUDAD. FUERA de la línea = INTERIOR/Servientrega: Panamá Oeste (Arraiján, La Chorrera, Chame, Vacamonte, Cocolí), Colón, Chepo, Chilibre, Panamá Norte, Panamá Pacífico y las provincias.', '1) CIUDAD = zonas 1 a 4 de delivery de la geografía (Juan Díaz y Costa del Este; Lucre, Brisas y San Antonio; San Miguelito, Betania y Edison; centro y Ancón). Zonas 5 y 6 (Las Cumbres, Alcalde Díaz, Veranillo, Tocumen, Pacora, 24 de Diciembre, Pedregal): según la TENDENCIA HISTÓRICA de la tienda (Kenku suele INTERIOR; Nuvo y Oferfy, CIUDAD). Todo lo demás es INTERIOR/Servientrega: Panamá Oeste (Arraiján, La Chorrera, Chame, Vacamonte), Colón, Chepo, Chilibre, Panamá Pacífico y las provincias.'), '6) Ernesto Córdoba y Cabra (no están en el mapa): sin tendencia ni otra pista, «no_se». Caimitillo y Panamá Norte (fuera del mapa): INTERIOR salvo tendencia clara. Pan de Azúcar, Cerro Batea, Samaria, Cabima, Gonzalillo y Ciudad del Saber: CIUDAD salvo tendencia clara.', '6) Lugares en discusión (Pan de Azúcar, Cerro Batea, Samaria, Cabima, Gonzalillo, Ciudad del Saber, Caimitillo, Ernesto Córdoba, Cabra, Panamá Norte, zonas 5 y 6): sigue la tendencia de la tienda; mixta o sin datos, «no_se».')
where c.pais_id = (select id from paises where codigo = 'PA');
notify pgrst, 'reload schema';
